public class NameSortersTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String names(java.util.List<Person> people) {
        StringBuilder sb = new StringBuilder();
        for (Person p : people) {
            if (sb.length() > 0) {
                sb.append(",");
            }
            sb.append(p.name());
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        java.util.Comparator<Person> byAge = NameSorters.byAge();
        check("byAge() is not null", true, byAge != null);
        if (byAge != null) {
            java.util.List<Person> people = new java.util.ArrayList<>(java.util.List.of(
                    new Person("Cara", 41), new Person("Ben", 19), new Person("Ada", 30)));
            people.sort(byAge);
            check("byAge sorts youngest first", "Ben,Ada,Cara", names(people));
        }
        java.util.Comparator<Person> byName = NameSorters.byNameLengthThenAlpha();
        check("byNameLengthThenAlpha() is not null", true, byName != null);
        if (byName != null) {
            java.util.List<Person> people = new java.util.ArrayList<>(java.util.List.of(
                    new Person("Anna", 1), new Person("Dee", 2), new Person("Al", 3),
                    new Person("Abe", 4), new Person("Bo", 5)));
            people.sort(byName);
            check("byNameLengthThenAlpha order", "Al,Bo,Abe,Dee,Anna", names(people));
            java.util.List<Person> ties = new java.util.ArrayList<>(java.util.List.of(
                    new Person("Zoe", 9), new Person("Amy", 9)));
            ties.sort(byName);
            check("length tie broken alphabetically", "Amy,Zoe", names(ties));
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

