record Person(String name, int age) {
}

public class NameSorters {

    public static java.util.Comparator<Person> byAge() {
        return java.util.Comparator.comparingInt(Person::age);
    }

    public static java.util.Comparator<Person> byNameLengthThenAlpha() {
        return java.util.Comparator.comparingInt((Person p) -> p.name().length())
                .thenComparing(Person::name);
    }
}
